function actionLabel(action){const [area,verb]=action.split('.');return t(area==='application'?'applications':area==='review'?'reviews':area)+' · '+t({suspend:'suspend',reactivate:'reactivate',block:'block',restore:'restore',approved:'approved',changes_requested:'changes_requested'}[verb]||verb);}
$('login').onsubmit=e=>{e.preventDefault();run(async()=>{const f=new FormData(e.target),d=await api('/auth/login',{phone:f.get('phone'),password:f.get('password')});token=d.token;e.target.reset();$('loginLanguage').value=lang;$('passwordInput').type='password';passwordToggleLabel();if(!d.profile.isAdmin){await api('/auth/logout',{});token=null;throw new Error(t('adminRequired'));}document.body.classList.remove('signed-out');$('passwordInput').type='password';passwordToggleLabel();$('login').hidden=true;$('workspace').hidden=false;$('logout').hidden=false;await load();});};
$('logout').onclick=()=>run(async()=>{await api('/auth/logout',{});token=null;showLogin();});$('search').onsubmit=e=>{e.preventDefault();page=1;run(load);};$('status').onchange=()=>run(load);$('refresh').onclick=()=>run(load);$('previous').onclick=()=>run(async()=>{page--;await load();});$('next').onclick=()=>run(async()=>{page++;await load();});$('close').onclick=()=>{$('dialog').close();detailLoader=null;};function changeLanguage(event){lang=event.target.value;localStorage.setItem('sammy-admin-language',lang);translate();if(token)run(async()=>{await load();if($('dialog').open&&detailLoader){$('detailTitle').textContent=t(section==='applications'?'review':section);await detailLoader();}});}$('language').onchange=changeLanguage;$('loginLanguage').onchange=changeLanguage;function passwordToggleLabel(){const shown=$('passwordInput').type==='text';$('passwordToggle').textContent=t(shown?'hide':'show');$('passwordToggle').setAttribute('aria-label',t(shown?'hidePassword':'showPassword'));$('passwordToggle').setAttribute('aria-pressed',String(shown));}$('passwordToggle').onclick=()=>{$('passwordInput').type=$('passwordInput').type==='password'?'text':'password';passwordToggleLabel();};translate();showLogin();
